+static void kmeansAssign(
+	const pixelBlock& block,
+	unsigned int pixelCount,
+	unsigned int partitionCount,
+	const vfloat4 clusterCenters[BLOCK_MAX_PARTITIONS],
+	uint8_t partitionOfPixel[BLOCK_MAX_PIXELS]
