+    auto *DefChainPhi = cast<MemoryPhi>(DefChainEnd);
+
+    PriorPathsSize = Paths.size();
+    PausedSearches.clear();
+    for (ListIndex I : NewPaused)
+        addSearches(DefChainPhi, PausedSearches, I);
+    NewPaused.clear();
