+  const uint8_t* const byteStream = dmuxPtr->memoryBuffer_;
+  size_t byteSize = 0;
+  const uint8_t* const payload = GetFramePayload(byteStream, frameData, &byteSize);
+  if (payload == NULL) return 0;
