+void RescheduleDAGSDNodes::ClusterNeighboringStores(Node *Node) {
+  SDValue Chain;
+  unsigned NumOps = Node->getNumOperands();
+  if (Node->getOperand(NumOps-1).getValueType() == MVT::Other)
+    Chain = Node->getOperand(NumOps-1);
