+inline bool
+BriskScaleSpace::isPeak2D(const int level, const int xLevel, const int yLevel)
+{
+  const cv::Mat& scores = pyramid_[level].scores();
+  const int cols = scores.cols;
+  const uchar* ptr = scores.ptr<uchar>() + yLevel * cols + xLevel;
+  // decision tree:
+  const uchar center = *ptr;
+  --ptr;
+  const uchar s10 = *ptr;
+  if (center > s10)
+    return true;
+  ++ptr;
+  const uchar s1_1 = *ptr;
+  if (center > s1_1)
+    return true;
+  ptr += cols + 2;
+  const uchar s01 = *ptr;
+  if (center > s01)
+    return true;
+  ptr -= cols - 1;
+  const uchar s0_1 = *ptr;
+  if (center > s0_1)
+    return true;
+  ptr += 2 * cols - 2;
+  const uchar s11 = *ptr;
+  if (center > s11)
+    return true;
+
+  // reject neighbor maxima
+  std::vector<int> offsets;
+  // collect 2d-offsets where the maximum is also reached
+  if (center == s0_1)
+  {
+    offsets.push_back(0);
+    offsets.push_back(-1);
+  }
+  if (center == s10)
+  {
+    offsets.push_back(1);
+    offsets.push_back(0);
+  }
+  if (center == s11)
+  {
+    offsets.push_back(1);
+    offsets.push_back(1);
+  }
+  if (center == s_11)
+  {
+    offsets.push_back(-1);
+    offsets.push_back(1);
+  }
+
+  const unsigned int size = static_cast<unsigned int>(offsets.size());
+  if (size != 0)
+  {
+    // analyze the situation more carefully
+    int smoothedCenter = 4 * center + 2 * (s_10 + s10 + s0_1 + s01) + s_1_1 + s1_1 + s_11 + s11;
+    for (unsigned int i = 0; i < size; ++i += 2)
+    {
+      ptr = scores.ptr<uchar>() + (yLevel - offsets[i + 1]) * cols + xLevel + offsets[i] - 1;
+      int otherCenter = *ptr;
+      ++ptr;
+      otherCenter += 2 * (*ptr);
+      ++ptr;
+      otherCenter += *ptr;
+      ptr += cols;
+      otherCenter += 2 * (*ptr);
+      --ptr;
+      otherCenter += 4 * (*ptr);
+      --ptr;
+      otherCenter += 2 * (*ptr);
+      ptr += cols;
+      otherCenter += *ptr;
+      ++ptr;
+      otherCenter += 2 * (*ptr);
+      ++ptr;
+      otherCenter += *ptr;
+      if (otherCenter >= smoothedCenter)
+        return false;
+    }
+  }
+  return true;
+}
