+void MassProperties::RescaleInertia(float newMass)
+{
+	if (mMass <= 0.0f)
+	{
+		mMass = newMass;
+		return;
+	}
+
+	float scale = newMass / mMass;
+
+	for (int i = 0; i < 3; ++i)
+	{
+		mInertia.SetColumn4(i, mInertia.GetColumn4(i) * scale);
+	}
+	mMass = newMass;
+}
